mapper.select:
select o.id,o.consignee,o.create_at, o.descrition,o.detail,o.img, o.mobile,number,o.order_num, o.pay_money,o.price,o.status, o.type,o.user_id, o.finish_time,o.pay_time,o.pay_way, o.coupon_user_id,o.commission_price,o.relation_id, o.provinces,o.express_name,o.express_number, o.refund,o.goods_id,o.is_express, o.is_refund,o.refused_refund,o.sku_id, o.pay_num,o.detail_json,o.group_sku_id, o.pink_id,o.seckill_id,o.pink_status, o.postage_price,o.group_pink_id,o.order_type, o.group_id,o.sec_kill_id,o.merchant_id, o.express_time,o.coupon_money,o.virtual_id, o.store_id,o.store_name,o.is_repeat, o.is_cart,o.day_id,o.one_money, o.one_user_id,o.two_money,o.two_user_id, o.lease_term,o.deposit,o.gross_rent, o.continue_date,o.cancel_time,o.lease_start_date, o.return_date,o.estimate_money,o.daily_rent, o.purchase_time,o.address_id,o.update_time, o.return_time,o.supplement_money,o.supplement_status, o.supplement_time,o.supplement_num,o.is_evaluate,o.total_continue_money, o.seller_number,o.delivery_time,o.send_phone,o.evaluation_time, o.overdue_status,o.buyout_price,g.title as title from orders o left join goods g on o.goods_id=g.id
and o.order_num like concat('%',#{orderNum},'%')
and o.status=#{status}
and g.title like concat('%',#{title},'%')
and o.mobile like concat('%',#{mobile},'%')
and o.store_id=#{storeId}
and o.is_express=#{isExpress}
and o.order_type=#{orderType}
and o.consignee like concat('%',#{consignee},'%')
and o.seller_number like concat('%',#{sellerNumber},'%')
and o.express_number like concat('%',#{expressNumber},'%')
and o.create_at >= #{startTime}
and o.create_at <= #{endTime}
order by o.create_at desc
